```js
// ==== Changes list hydration ====
// Populate #changes-list (changes.html) from site/log.json so the page's
// "full list, newest first" promise is kept and the export buttons have rows
// to work with. Only landed ticks are shown. If log.json is missing, the
// static HTML is left intact.
function hydrateChangesList() {
  const list = document.getElementById('changes-list');
  if (!list) return;
  fetch('log.json')
    .then(r => r.json())
    .then(entries => {
      const landed = (Array.isArray(entries) ? entries : [])
        .filter(e => e && e.state === 'landed')
        .sort((a, b) => String(b.run_at).localeCompare(String(a.run_at)));
      list.textContent = '';
      landed.forEach(e => {
        const li = document.createElement('li');
        li.textContent = e.run_at + ' — ' + e.changed_paths;
        list.appendChild(li);
      });
    })
    .catch(() => {
      // log.json unavailable; keep the static HTML
    });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', hydrateChangesList);
} else {
  hydrateChangesList();
}
```

